pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory tos, uint[] memory vs) public {
        // Ensure admissible array lengths
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);

        // Ensure no address in tos equals 0x0 or the c address itself (validAddress modifier)
        for(uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0x0));
            vm.assume(tos[i] != address(c));
        }

        // The contract makes low-level calls to 'contract_address'.
        // For those calls to succeed so that the loop completes without revert,
        // we need an external party that returns (true, ...) on transferFrom.
        // Deploy a helper that does exactly that.
        SuccessfulCallee helper = new SuccessfulCallee();
        address contract_address = address(helper);

        // Ensure contract_address itself passes the validAddress check
        vm.assume(contract_address != address(0x0));
        vm.assume(contract_address != address(c));

        // Execute the transfer. The function should not revert (all calls succeed)
        // and the return value differs between reference and mutant.
        bool result = c.transfer(contract_address, tos, vs);
        // The correct contract C returns true; the mutant returns false.
        assertTrue(result);
    }
}

contract SuccessfulCallee {
    // transferFrom returns true on any input, so the low-level call succeeds
    function transferFrom(address, address, uint256) external pure returns (bool) {
