pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address[] memory tos, uint[] memory vs) public {
        // Restrict to admissible domain: both arrays non-empty (required by existing checks)
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        // Ensure the maximum array length difference does not cause a static OOG revert
        vm.assume(tos.length <= 100);
        vm.assume(vs.length <= 100);

        // Deploy an adversarial counterparty: a mock ERC20-like contract that exposes
        // a public getter for the last call arguments so we can tell whether c performed
        // the unchecked external call. Without a helper, the fuzzer only supplies EOAs
        // that always succeed on low-level calls, which would mask the bug if the call
        // happens to succeed even when reading garbage from a too-short vs array.
        // The helper reverts when called with zero value (to make the bug-triggering
        // reversion detectable), and stores call data for inspection.
        MockERC20 mock = new MockERC20();
        // The contract_address parameter is the mock address.
        address contract_address = address(mock);

        // Call transfer with the fuzzed arrays.
        // Since the function expects contract_address to implement transferFrom, we
        // pass the mock and let fuzzer choose arrays.
        bool success;
        try c.transfer(contract_address, tos, vs) returns (bool v) {
            success = v;
        } catch {
            success = false;
        }

        // GENERAL RULE: If tos.length != vs.length, the call MUST revert.
        // The reference enforces this via the deleted require; the buggy version
        // proceeds into the loop where an out-of-bounds read from vs (when vs is shorter)
        // causes a dirty internal call that can succeed or fail, violating the invariant.
        // The assertion: if lengths mismatch, success must be false.
        bool lengthsEqual = (tos.length == vs.length);
        assertTrue(lengthsEqual || !success);
    }
}

/// Minimal helper that records the latest call and can revert on receiving zero value
/// to expose the buggy behavior when the corrupted call sends less value than expected.
contract MockERC20 {
    address public lastFrom;
    address public lastTo;
    uint256 public lastValue;

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        // Revert when value is 0 because the bug can read zero from an out-of-bounds
        // vs element and the real party would typically revert on zero transfer.
        // This ensures the buggy version's stray call fails when vs is too short,
        // making the invariant violation observable.
        if (value == 0) revert("zero transfer");
        return true;
    }
}

