pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, address sender, address to, uint256 value) public {
        vm.assume(sender != address(0x0));
        vm.assume(sender != address(c));
        vm.assume(to != address(0x0));
        vm.assume(to != address(c));
        vm.assume(target != address(0x0));
        vm.assume(target != address(c));
        vm.assume(target != sender);
        vm.assume(target != to);
        vm.assume(value > 0);

        // Deploy adversarial helper that has both transfer and transferFrom.
        // transferFrom reverts unless allowance is set, transfer reverts unless target has balance.
        // We expect the reference (call transferFrom) to revert without allowance,
        // while the buggy (call transfer) uses target's balance which we don't fund, causing revert too.
        // To create a difference, we need a helper where one call succeeds and the other fails.
        DualFunctionHelper helper = new DualFunctionHelper();

        // Fund the helper with value, so transfer(address,uint256) can succeed on the helper.
        vm.deal(address(helper), value);
        // Do NOT set allowance, so transferFrom will fail.

        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vs = new uint[](1);
        vs[0] = value;

        // Reference: transferFrom(address,address,uint256) should revert (no allowance).
        // Buggy: transfer(address,uint256) should succeed (helper has balance).
        // We call from 'sender' through C.

        vm.prank(sender);
        bool okRef;
        try c.transfer(address(helper), tos, vs) {
            okRef = true;
        } catch {
            okRef = false;
        }

        // The property: outcome of transfer is deterministic based on selector used.
        // Since reference always uses transferFrom, and buggy always uses transfer,
        // the buggy will succeed here while reference fails.
        // So assertTrue(okRef == false) holds for reference, but fails for buggy.
        assertTrue(okRef == false);
    }
}

contract DualFunctionHelper {
    // Must have both transfer and transferFrom signature.
    // We make transfer succeed (just emit something) and transferFrom revert unless allowance is non-zero.
    // We don't need allowance mapping because C will call with msg.sender.
    // transferFrom will simply revert.
    function transfer(address recipient, uint256 amount) external payable returns (bool) {
        // succeed silently
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        // always revert to mimic no allowance/balance
        revert("transferFrom disallowed");
    }

    // receive Ether to have balance
    receive() external payable {}
}

